begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();sid uuid;iid uuid:=gen_random_uuid();req uuid:=gen_random_uuid();j uuid;j2 uuid;job jsonb;info jsonb;candidate jsonb;bad jsonb;result jsonb;cat uuid;article uuid;
begin
 insert into auth.users(id,email) values(u,'z09-'||u||'@example.invalid'),(v,'z09-'||v||'@example.invalid');
 insert into private.profiles(id) values(u),(v);insert into private.user_roles(user_id,role) values(u,'editor'),(v,'editor');
 perform set_config('request.jwt.claim.sub',u::text,true);
 result:=api.editor_save_source(null,null,'Fuente ficticia','https://example.org/feed','example.org','rss','Prueba local',true);sid:=(result->>'id')::uuid;
 insert into private.source_items(id,source_id,canonical_url,title,external_date) values(iid,sid,'https://example.org/item','SIMULACIÓN noticia ficticia','2026-11-09T12:00:00Z');
 result:=api.enqueue_ollama_draft(iid,req);j:=(result->>'id')::uuid;
 if (api.enqueue_ollama_draft(iid,req)->>'id')::uuid<>j then raise exception 'IDEMPOTENCY_FAILED';end if;
 perform set_config('request.jwt.claim.sub',v::text,true);
 if jsonb_array_length(api.editor_fixture_jobs())<>0 then raise exception 'OTHER_EDITOR_JOB_EXPOSED';end if;
 begin perform api.cancel_editor_job(j);raise exception 'OTHER_EDITOR_CANCELLED';exception when no_data_found then null;end;
 perform set_config('role','riuya_job_executor',true);
 job:=private.claim_job('test-ollama',60);if job->>'id'<>j::text then raise exception 'CLAIM_FAILED';end if;
 info:=private.ollama_job_info(j,(job->>'leaseToken')::uuid);if info->'source'->>'url'<>'https://example.org/item' then raise exception 'WRONG_SOURCE';end if;
 perform set_config('role','none',true);perform set_config('request.jwt.claim.sub',u::text,true);
 result:=api.cancel_editor_job(j);if result->>'status'<>'cancelled' then raise exception 'CANCEL_FAILED';end if;
 perform set_config('role','riuya_job_executor',true);
 if private.complete_ollama_draft(j,(job->>'leaseToken')::uuid,'{}','qwen3:8b',repeat('a',64),1) then raise exception 'CANCELLED_JOB_COMPLETED';end if;
 perform set_config('role','none',true);
 result:=api.enqueue_ollama_draft(iid,gen_random_uuid());j2:=(result->>'id')::uuid;
 perform set_config('role','riuya_job_executor',true);
 job:=private.claim_job('test-ollama',60);if job->>'id'<>j2::text then raise exception 'CLAIM_SECOND_FAILED';end if;
 info:=private.ollama_job_info(j2,(job->>'leaseToken')::uuid);
 select jsonb_build_object('title','SIMULACIÓN propuesta','summary','Resumen ficticio','paragraphs',jsonb_build_array('Hecho de prueba [f1]'),'sources',jsonb_build_array(info->'source'),'opinions',jsonb_agg(jsonb_build_object('characterKey',k,'body','Texto ficticio') order by k)) into candidate from unnest(array['rami','beatriz','leo','dmitri','naoki','salma','tove','kavya']) k;
 bad:=jsonb_set(candidate,'{paragraphs}','["Cita falsa [f2]"]');
 begin perform private.complete_ollama_draft(j2,(job->>'leaseToken')::uuid,bad,'qwen3:8b',repeat('a',64),1);raise exception 'BAD_CITATION_ACCEPTED';exception when invalid_parameter_value then null;end;
 bad:=jsonb_set(candidate,'{sources}','[]');
 begin perform private.complete_ollama_draft(j2,(job->>'leaseToken')::uuid,bad,'qwen3:8b',repeat('a',64),1);raise exception 'BAD_SOURCE_ACCEPTED';exception when invalid_parameter_value then null;end;
 if not private.complete_ollama_draft(j2,(job->>'leaseToken')::uuid,candidate,'qwen3:8b',repeat('a',64),1) then raise exception 'VALID_FAILED';end if;
 if not exists(select 1 from private.generation_runs where job_id=j2 and provider='ollama' and model_digest=repeat('a',64)) then raise exception 'RUN_MISSING';end if;
 perform set_config('role','none',true);perform set_config('request.jwt.claim.sub',u::text,true);
 select id into cat from private.categories where is_active limit 1;
 begin perform api.import_generated_draft(j2,cat,false);raise exception 'IMPORT_WITHOUT_CONFIRM';exception when invalid_parameter_value then null;end;
 result:=api.import_generated_draft(j2,cat,true);article:=(result->>'id')::uuid;
 if not exists(select 1 from private.articles where id=article and status='draft') then raise exception 'IMPORT_NOT_DRAFT';end if;
 result:=api.import_generated_draft(j2,cat,true);
 if (result->>'id')::uuid<>article or not (result->>'replayed')::boolean then raise exception 'IMPORT_NOT_IDEMPOTENT';end if;
 perform set_config('request.jwt.claim.sub',v::text,true);
 begin perform api.import_generated_draft(j2,cat,true);raise exception 'OTHER_EDITOR_IMPORT';exception when no_data_found then null;end;
end $$;
rollback;
